def max_area_of_island(grid):
    if not grid:
        return 0
    grid = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])
    def area(r, c):
        stack = [(r, c)]
        size = 0
        while stack:
            cr, cc = stack.pop()
            if cr < 0 or cc < 0 or cr >= rows or cc >= cols or grid[cr][cc] != 1:
                continue
            grid[cr][cc] = 0
            size += 1
            stack.extend([(cr + 1, cc), (cr - 1, cc), (cr, cc + 1), (cr, cc - 1)])
        return size
    best = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                best = max(best, area(r, c))
    return best

reference_solution:
def max_area_of_island(grid):
    if not grid:
        return 0
    grid = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])
    visited = set()
    def dfs(r, c):
        if r < 0 or c < 0 or r >= rows or c >= cols:
            return 0
        if grid[r][c] != 1 or (r, c) in visited:
            return 0
        visited.add((r, c))
        return 1 + dfs(r + 1, c) + dfs(r - 1, c) + dfs(r, c + 1) + dfs(r, c - 1)
    best = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and (r, c) not in visited:
                best = max(best, dfs(r, c))
    return best
